#!/usr/bin/env node
// Generated by ai-factory. Stop hook: refuses to end the turn while the repo's
// own validation commands fail.
//
// Why a hook and not a prompt: every builder prompt already says "run the
// validation commands before returning, do not return with failing checks".
// Nothing ever verified that. This does — the harness runs them, so a builder
// cannot report green while the suite is red.
//
// Reads factory-stop.json (next to this file):
//   { "typecheck": "<cmd>", "test": "<cmd>" }   // either key may be absent
//
// Deliberately NOT a hard gate. Stop fires at the end of every assistant turn,
// so three guards keep it from trapping the session:
//   1. `stop_hook_active` short-circuits — a blocked stop can never loop.
//   2. A clean working tree exits immediately: nothing was edited, nothing to check.
//   3. The working-tree fingerprint is remembered, so it blocks at most once per
//      distinct state. Asking a question in a repo that already has failing tests
//      does not re-block every turn.
// State lives in the OS temp dir, keyed by repo path — nothing is written to the repo.
//
// Do not hand-edit — edit .factory.yaml and re-run `factory install`.
import { readFileSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";
import { createHash } from "node:crypto";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));

let config = {};
try {
  config = JSON.parse(readFileSync(join(here, "factory-stop.json"), "utf8"));
} catch {
  process.exit(0); // no config → nothing to enforce
}

let data = {};
try { data = JSON.parse(readFileSync(0, "utf8") || "{}"); } catch {}
if (!data || typeof data !== "object") data = {};

// Guard 1: never block twice in a row.
if (data.stop_hook_active) process.exit(0);

const cwd = data.cwd || process.cwd();

// A shell is intentional, not an oversight. The only interpolated values are
// `commands.typecheck` / `commands.test` from .factory.yaml, which are shell
// strings by definition — repos write `pnpm test`, `uv run pytest -q`, or a
// pipeline. They come from the same trusted manifest that decides this hook
// runs at all, so there is no lower-privilege input to protect here. Every
// other command below is a constant.
function sh(cmd) {
  return execSync(cmd, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: 600000 });
}

// Guard 2: a clean tree means the turn changed nothing worth validating.
// Also our only way to fingerprint state, so a non-git repo opts out entirely.
let fingerprint;
try {
  const status = sh("git status --porcelain");
  if (status.trim() === "") process.exit(0);
  fingerprint = createHash("sha256").update(status).update(sh("git diff HEAD")).digest("hex");
} catch {
  process.exit(0);
}

const stateFile = join(
  tmpdir(),
  `factory-stop-${createHash("sha256").update(cwd).digest("hex").slice(0, 16)}.json`,
);
let state = {};
try { state = JSON.parse(readFileSync(stateFile, "utf8")); } catch {}

// Guard 3: this exact state was already validated, or already reported.
if (state.lastPass === fingerprint || state.lastBlocked === fingerprint) process.exit(0);

function saveState(next) {
  try { writeFileSync(stateFile, JSON.stringify(next)); } catch {}
}

function tail(text, lines) {
  const all = String(text).split("\n");
  return all.length <= lines ? all.join("\n") : all.slice(-lines).join("\n");
}

for (const key of ["typecheck", "test"]) {
  const cmd = config[key];
  if (typeof cmd !== "string" || cmd.trim() === "") continue;
  try {
    sh(cmd);
  } catch (err) {
    saveState({ ...state, lastBlocked: fingerprint });
    const output = tail(String(err.stdout ?? "") + String(err.stderr ?? ""), 40);
    console.error(
      `Blocked by ai-factory: \`${cmd}\` (${key}) is failing, and the working tree has uncommitted changes.\n\n` +
        `${output}\n\n` +
        `Fix the cause and re-run \`${cmd}\`. Do not disable, skip or comment out checks to get past this.\n` +
        `(This reports once per distinct working-tree state; it will not block again until something changes.)`,
    );
    process.exit(2);
  }
}

saveState({ ...state, lastPass: fingerprint });
process.exit(0);
